<script>
  /**
   * Inline SVG renderer for files under `/src/svg` or `/src/svgs`.
   *
   * - Renders the raw SVG content via `import.meta.glob` lookups.
   * - No slot support; `children` is intentionally dropped.
   *
   * @component
   * @example
   *   <!-- Renders /src/svg/logo.svg -->
   *   <SVG name="logo" class="w-6 h-6" />
   * @example
   *   <!-- Use DOM parser when the SVG needs runtime DOM APIs -->
   *   <SVG name="spinner" parser="dom" style={{ color: 'rebeccapurple' }} />
   * @throws {Error} When both name and icon are missing
   * @throws {Error} When the requested SVG file cannot be found
   */

  /**
   * @typedef {object} SVGProps
   * @property {string} [name] - Basename of the SVG file (without .svg)
   * @property {string} [icon] - Alias of name. Use whichever reads better
   * @property {object|string} [style] - Inline styles. Object is converted with `toStyleString`
   * @property {"naive"|"dom"} [parser="naive"] - Parsing strategy
   * @property {*} [children] - Ignored; component does not support slots
   */
  import { toStyleString } from '@splendidlabz/utils'
  import { onMount } from 'svelte'
  import { domParser, naiveParser } from './parser.js'
  import { init } from '../../utils'
  /** @type {SVGProps} */
  const {
    icon,
    name,
    style,
    parser = 'naive', // or DOM
    children, // Just to remove children slots
    ...rest
  } = $props()

  const basename = name || icon

  const files = {
    ...import.meta.glob(`/src/svg/**/*.svg`, { eager: true, query: 'raw' }),
    ...import.meta.glob(`/src/svgs/**/*.svg`, { eager: true, query: 'raw' }),
  }

  // Find the SVG
  const file = init(() => {
    if (!basename) throw new Error('name (or icon) property is required')
    const found = Object.keys(files).find(
      f => f.split('/').pop() === `${basename}.svg`,
    )
    if (!found) throw new Error(`${basename}.svg not found`)
    return found
  })

  const content = files[file].default

  function buildSvgProps() {
    return {
      role: 'img',
      xmlns: 'http://www.w3.org/2000/svg',
      style: toStyleString(style),
      ...rest,
    }
  }

  let svg = $state(null)

  init(() => {
    if (parser === 'naive') svg = naiveParser(content, buildSvgProps())
    if (parser === 'dom') {
      onMount(_ => {
        svg = domParser(content, buildSvgProps())
      })
    }
  })
</script>

<!--
@component
Inline SVG renderer for files under `/src/svg` or `/src/svgs`.

- Props:
  - name (string): Basename of the SVG file (without .svg)
  - icon (string): Alias of name. Use whichever reads better
  - style (object|string, optional): Inline styles; objects are converted with `toStyleString`
  - parser ("naive"|"dom", optional, default "naive"): Parsing strategy
- Slots: none
- Events: none
- Errors:
  - Throws if both `name` and `icon` are missing
  - Throws if the SVG file cannot be found

Usage:
```svelte
<SVG name="logo" class="w-6 h-6" />
<SVG name="spinner" parser="dom" style={{ color: 'rebeccapurple' }} />
```
-->

<!-- eslint-disable-next-line svelte/no-at-html-tags -->
{@html svg}
